keyframes.shimmer:
@keyframes shimmer { 
  0% { background-position: 0px center; }
  50% { background-position: 100% center; }
  100% { background-position: 0px center; }
}

keyframes.selector-shimmer:
@keyframes selector-shimmer { 
  0%, 100% { opacity: 0; transform: translate(-100%); }
  50% { opacity: 1; transform: translate(100%); }
}

keyframes.chevron-tap:
@keyframes chevron-tap { 
  0%, 100% { color: rgb(156, 163, 175); filter: brightness(); transform: translateY(0px) scale(1); }
  20% { color: rgb(244, 114, 182); filter: brightness(1.3) drop-shadow(rgb(244, 114, 182) 0px 0px 4px); transform: translateY(4px) scale(1.15); }
  30% { color: rgb(244, 114, 182); filter: brightness(1.2); transform: translateY(0px) scale(1); }
  40% { color: rgb(244, 114, 182); filter: brightness(1.3) drop-shadow(rgb(244, 114, 182) 0px 0px 4px); transform: translateY(4px) scale(1.15); }
  50% { color: rgb(156, 163, 175); filter: brightness(); transform: translateY(0px) scale(1); }
}

keyframes.fadeIn:
@keyframes fadeIn { 
  0% { opacity: 0; transform: translateY(-10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes.modalSlideUp:
@keyframes modalSlideUp { 
  0% { opacity: 0; transform: translateY(100%); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes.modalScaleIn:
@keyframes modalScaleIn { 
  0% { opacity: 0; transform: scale(0.95); }
  100% { opacity: 1; transform: scale(1); }
}

keyframes.staggerFadeIn:
@keyframes staggerFadeIn { 
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes.bounce:
@keyframes bounce { 
  0%, 100% { animation-timing-function: cubic-bezier(0.8, 0, 1, 1); transform: translateY(-25%); }
  50% { animation-timing-function: cubic-bezier(0, 0, 0.2, 1); transform: none; }
}

keyframes.driverPulse:
@keyframes driverPulse { 
  0% { box-shadow: rgba(251, 53, 109, 0.6) 0px 0px 0px 0px; }
  70% { box-shadow: rgba(251, 53, 109, 0) 0px 0px 0px 12px; }
  100% { box-shadow: rgba(251, 53, 109, 0) 0px 0px 0px 0px; }
}

keyframes.pointerBounce:
@keyframes pointerBounce { 
  0%, 100% { transform: translateX(-50%) translateY(0px); }
  50% { transform: translateX(-50%) translateY(-8px); }
}

keyframes.shake:
@keyframes shake { 
  0%, 100% { transform: translateX(0px); }
  20% { transform: translateX(-8px); }
  40% { transform: translateX(8px); }
  60% { transform: translateX(-6px); }
  80% { transform: translateX(6px); }
}

keyframes.driverPopoverFadeIn:
@keyframes driverPopoverFadeIn { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

keyframes.go2264125279:
@keyframes go2264125279 { 
  0% { transform: scale(0) rotate(45deg); opacity: 0; }
  100% { transform: scale(1) rotate(45deg); opacity: 1; }
}

keyframes.go3020080000:
@keyframes go3020080000 { 
  0% { transform: scale(0); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

keyframes.go463499852:
@keyframes go463499852 { 
  0% { transform: scale(0) rotate(90deg); opacity: 0; }
  100% { transform: scale(1) rotate(90deg); opacity: 1; }
}

keyframes.go1310225428:
@keyframes go1310225428 { 
  0% { transform: scale(0) rotate(45deg); opacity: 0; }
  100% { transform: scale(1) rotate(45deg); opacity: 1; }
}

keyframes.go651618207:
@keyframes go651618207 { 
  0% { height: 0px; width: 0px; opacity: 0; }
  40% { height: 0px; width: 6px; opacity: 1; }
  100% { opacity: 1; height: 10px; }
}

keyframes.go901347462:
@keyframes go901347462 { 
  0% { transform: scale(0.6); opacity: 0.4; }
  100% { transform: scale(1); opacity: 1; }
}

keyframes.envelope-away:
@keyframes envelope-away { 
  0% { transform: translateY(0px) rotate(0deg); opacity: 1; }
  15% { transform: translateY(10px) rotate(0.5deg); opacity: 1; }
  100% { transform: translateY(-120vh) rotate(-2deg); opacity: 0; }
}

keyframes.particle-burst:
@keyframes particle-burst { 
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0) rotate(0deg); }
  15% { opacity: 1; transform: translate(-50%,-50%)scale(1.3)rotate(var(--rot-start,15deg)); }
  100% { opacity: 0; transform: translate(calc(-50% + var(--dx)),calc(-50% + var(--dy)))scale(.6)rotate(var(--rot-end,180deg)); }
}

keyframes.seal-pulse:
@keyframes seal-pulse { 
  0%, 100% { transform: translate(-50%, -50%) scale(1); box-shadow: 0 4px 20px var(--shadow-color); }
  50% { transform: translate(-50%, -50%) scale(1.06); box-shadow: 0 6px 35px var(--shadow-color); }
}

keyframes.seal-break:
@keyframes seal-break { 
  0% { transform: translate(-50%, -50%) scale(1) rotate(0deg); opacity: 1; filter: brightness(1); }
  30% { transform: translate(-50%, -50%) scale(1.15) rotate(5deg); opacity: 0.9; filter: brightness(1.3); }
  60% { transform: translate(-50%, -50%) scale(1.05) rotate(-3deg); opacity: 0.5; filter: brightness(1.5); }
  100% { transform: translate(-50%, -50%) scale(0) rotate(15deg); opacity: 0; filter: brightness(2); }
}

keyframes.seal-ring:
@keyframes seal-ring { 
  0% { transform: translate(-50%, -50%) scale(0.8); opacity: 0.8; }
  100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
}

keyframes.seal-flower-bloom:
@keyframes seal-flower-bloom { 
  0% { transform: scale(1) rotate(0deg); filter: brightness(1); }
  45% { transform: scale(1.16) rotate(-3deg); filter: brightness(1.08); }
  100% { transform: scale(1.06) rotate(0deg); filter: brightness(1.02); }
}

keyframes.dragon-fly-forward:
@keyframes dragon-fly-forward { 
  0% { transform: scale(var(--fly-scale-x,1),1); filter: blur(0px); opacity: 0.7; }
  40% { transform: scale(calc(var(--fly-scale-x,1)*1.6),1.6); filter: blur(2px); opacity: 0.5; }
  100% { transform: scale(calc(var(--fly-scale-x,1)*3),3); filter: blur(10px); opacity: 0; }
}

keyframes.ambient-fall:
@keyframes ambient-fall { 
  0% { transform: translateY(-8vh) translateX(0px) rotate(0deg); opacity: 0; }
  10% { opacity: 0.5; }
  50% { transform: translatey(48vh)translatex(var(--sway,20px))rotate(180deg); opacity: 0.6; }
  92% { opacity: 0.45; }
  100% { transform: translateY(105vh) translateX(0px) rotate(360deg); opacity: 0; }
}

keyframes.ambient-rise:
@keyframes ambient-rise { 
  0% { transform: translateY(6vh) translateX(0px) rotate(0deg); opacity: 0; }
  12% { opacity: 0.45; }
  55% { transform: translatey(-42vh)translatex(var(--sway,20px))rotate(8deg); opacity: 0.55; }
  92% { opacity: 0.35; }
  100% { transform: translateY(-92vh) translateX(0px) rotate(0deg); opacity: 0; }
}

